    latency_p95_ms double precision
    modality text NOT NULL
    output_tokens_total bigint NOT NULL
    request_count bigint NOT NULL
    tag_key text NOT NULL
    tag_value text NOT NULL
    uptime double precision DEFAULT (((request_count - error_count))::double precision / (NULLIF(request_count, 0))::double precision)
    CONSTRAINT stats_tags_hourly_pkey PRIMARY KEY (modality, customer_id, tag_key, tag_value, bucket)

TABLE turn_latency_hourly
    agent_id text NOT NULL
    bin smallint NOT NULL
    bucket timestamp with time zone NOT NULL
    count bigint NOT NULL
    customer_id text NOT NULL
    leg text NOT NULL
    CONSTRAINT turn_latency_hourly_pkey PRIMARY KEY (customer_id, agent_id, bucket, leg, bin)

TABLE turn_stats_hourly
    agent_id text NOT NULL
    audio_out_ms_total double precision NOT NULL
    bucket timestamp with time zone NOT NULL
    customer_id text NOT NULL
    interrupted_count bigint NOT NULL
    turn_count bigint NOT NULL
    CONSTRAINT turn_stats_hourly_pkey PRIMARY KEY (customer_id, agent_id, bucket)
